const int N = 111, mod = 998244353;

char s[N];
int dig[N], n;

int gcd(int x, int y) {
  return x ? gcd(y % x, x) : y;
}

map<pair<int, int>, int> dp[2][2][10][10];

void add(int& var, int val) {
  var += val;
  if (var >= mod)
    var -= mod;
}

int to1[10], to2[10];

long long solve(int x, int y) {
  int c = 0, b = 1;

  memset(to1, 0, sizeof to1);
  memset(to2, 0, sizeof to2);

  for (int i = 1; i * y < 10; ++i) {
    to1[i * x] = 1 << (i - 1);
    to2[i * y] = 1 << (i - 1);
  }

  for (int layer = 0; layer < 2; ++layer)
    for (int more = 0; more < 2; ++more)
      for (int l = 0; l < 10; ++l)
        for (int r = 0; r < 10; ++r)
          dp[layer][more][l][r].clear();

  dp[c][0][0][0][{0, 0}] = 1;

  for (int i = 0; i < n; ++i) {
    swap(c, b);

    for (int more = 0; more < 2; ++more)
      for (int l = 0; l < 10; ++l)
        for (int r = 0; r < 10; ++r)
          dp[c][more][l][r].clear();

    for (int more = 0; more < 2; ++more) {
      for (int l = 0; l < 10; ++l) {
        for (int r = 0; r < 10; ++r) {
          for (const auto& it : dp[b][more][l][r]) {
            int now = it.second;
            int maska = it.first.first;
            int maskb = it.first.second;

            for (int k = 0; k < 10; ++k) {
              int ll = l + x * k;
              int rr = r + y * k;
              int dl = ll % 10;
              int dr = rr % 10;
              ll /= 10;
              rr /= 10;

              int nextMore;
              if (dr > dig[i])
                nextMore = 1;
              else if (dr < dig[i])
                nextMore = 0;
              else
                nextMore = more;

              int nextMaskA = maska;
              int nextMaskB = maskb;

              if (nextMaskA != -1) {
                nextMaskA |= to1[dl];
                nextMaskB |= to2[dr];

                if (nextMaskA & nextMaskB)
                  nextMaskA = nextMaskB = -1;
              }

              add(dp[c][nextMore][ll][rr][{nextMaskA, nextMaskB}], now);
            }
          }
        }
      }
    }
  }

  int ans = 0;
  for (const auto& it : dp[c][0][0][0]) {
    if (it.first.first & it.first.second)
      add(ans, it.second);
  }
  return ans;
